"""Generate the R3 C1–C5 synthesis from the saved numerical artifacts."""
from pathlib import Path
import json
P=Path(__file__).resolve().parent
def read(path):return json.loads((P/path).read_text(encoding='utf-8'))
def main():
    c1=read('C1/results.json')['results'];c2=read('C2/results.json');c3=read('C3/revision_v2/results.json')['models'];c4=read('C4/results.json')['models'];c5=read('C5/results.json')['models']
    p=c1['pic2word']['comparison'][2];n=c2['selection']['pic2word'];s=c2['selection']['searle'];geom=c4['pic2word']['geometry']; sg=c4['searle']['geometry'];a=c4['pic2word']['n10']; k=c5['pic2word'];v=c5['searle']; pp=lambda x:x*100
    lines=['# Tổng hợp kết quả R3: C1–C5','','## Kết luận chính','',f"Trên CIRCO và cấu hình đã khảo sát, centering cho Pic2Word tăng retention tại **cùng số phép tính khoảng cách** trong C1. Ví dụ, ở khoảng **{p['ndis_per_query']:.0f} ndis/query**, retention tăng từ **{pp(p['original_retention']):.2f}%** lên **{pp(p['centered_retention']):.2f}%**, chênh lệch **{pp(p['delta']):+.2f} điểm phần trăm** (CI 95% [{pp(p['ci_lower']):+.2f}; {pp(p['ci_upper']):+.2f}]). Tuy nhiên, C2 **chưa khớp được số cạnh** theo tiêu chí định trước, nên chưa xác định được lợi thế khi đồng thời kiểm soát mật độ đồ thị.",'', 'C4 cho thấy centering thay đổi cấu trúc đồ thị và các thống kê gallery; những thay đổi này là cơ chế cần kiểm tra, chưa phải bằng chứng nhân quả. C5 cho thấy query Pic2Word có `s1` thấp nhất nhận gain lớn hơn nhóm cao nhất tại cùng `efSearch`, nhưng chưa đạt xu hướng đơn điệu trên cả năm nhóm.','', '## Phạm vi và cách đọc','', 'Các thí nghiệm dùng CIRCO, 123.403 ảnh gallery và 1.020 query mỗi backbone; HNSW reference `M=32`, `efConstruction=200`, năm seed. Retention@10 là tỷ lệ ảnh trong top-10 exact được HNSW tìm lại, không phải mAP hay recall theo nhãn. Chênh lệch retention/miss được báo bằng **điểm phần trăm**. Centering IP trừ mean khỏi gallery đã chuẩn hóa, không chuẩn hóa lại và giữ query CIR; exact ranking IP được kiểm tra trực tiếp.','', '## C1 — Cùng chi phí tìm kiếm','', f"- **Pic2Word:** centered cao hơn original tại cả {sum(x['ci_lower']>0 for x in c1['pic2word']['comparison'])}/5 ngân sách `ndis` chung; CI ghép cặp tại từng điểm đều dương. Khoảng khảo sát và kết quả từng điểm có trong [báo cáo C1](./C1/bao_cao_C1.md).", f"- **SEARLE:** {sum(x['ci_lower']<=0<=x['ci_upper'] for x in c1['searle']['comparison'])}/5 CI chênh lệch chứa 0. Chưa có bằng chứng lợi thế tại cùng `ndis`; không phải chứng minh hai phương án tương đương.",'', 'So sánh tại cùng `ndis` đã kiểm soát số phép tính tìm kiếm trung bình; nó chưa tự kiểm soát số cạnh, bộ nhớ hoặc chi phí dựng. CI theo từng điểm không phải CI đồng thời; nội suy và năm seed giới hạn kết luận.','', '## C2 — Cùng mật độ đồ thị','', f"Ngưỡng khớp đã đăng ký là sai lệch median số cạnh tầng 0 không quá 2%. Trong các `M` original đã quét, mức gần nhất đều là `M={n['selected_M']}`, nhưng Pic2Word vẫn lệch **{pp(n['median_relative_deviation']):+.2f}%** so với centered `M=32`; SEARLE lệch **{pp(s['median_relative_deviation']):+.2f}%**. **Không model nào đạt tiêu chí khớp.**",'', 'Các đường retention–ndis ở mức M gần nhất là so sánh xấp xỉ. Chưa thể dùng C2 để kết luận centering hơn hay tương đương original tại cùng mật độ. [Báo cáo C2](./C2/bao_cao_C2.md).','', '## C3 — Đối chứng tịnh tiến L2','', 'Trừ cùng mean khỏi query và gallery giữ nguyên khoảng cách L2 về mặt toán học. Trong phép kiểm tra FAISS float32, tập exact top-10 giống nhau trên toàn bộ query ở cả hai model. SEARLE có một query đảo thứ tự hai ảnh gần hòa; Pic2Word không có query đổi thứ tự. Tiêu chí chấp nhận đảo thứ tự gần hòa được bổ sung **sau khi quan sát**, nên cần báo cùng kết quả ban đầu.','', f"Trên năm seed ở `efSearch=128`, chênh lệch retention centered − original trung bình là **{pp(c3['searle']['mean_delta']):+.3f} điểm %** với SEARLE và **{pp(c3['pic2word']['mean_delta']):+.3f} điểm %** với Pic2Word; số cạnh hoặc `ndis` có sai khác nhỏ ở một số seed. Kết quả phù hợp với đối chứng L2, không tự chứng minh cơ chế của IP. [Báo cáo C3](./C3/revision_v2/bao_cao_C3.md).",'', '## C4 — Hình học gallery và cấu trúc đồ thị','', f"- MCS gốc: SEARLE **{sg['mcs_original_unit_formula']:.5f}**, Pic2Word **{geom['mcs_original_unit_formula']:.5f}**. Pic2Word cao hơn như dự đoán, nhưng chỉ riêng MCS chưa giải thích được khác biệt hiệu ứng centering giữa hai backbone.", f"- Với Pic2Word, tỷ lệ `N10_gallery=0` giảm từ **{pp(a['before']['zero_ratio']):.2f}%** xuống **{pp(a['after']['zero_ratio']):.2f}%**, trong khi skewness tăng từ **{a['before']['skewness']:.3f}** lên **{a['after']['skewness']:.3f}**. N10 gallery và bậc vào HNSW đo những cấu trúc khác nhau.", f"- Bậc vào trung bình của các exact-neighbor occurrence Pic2Word tăng từ **{c4['pic2word']['exact_neighbor_indegree']['before']['mean']:.2f}** lên **{c4['pic2word']['exact_neighbor_indegree']['after']['mean']:.2f}**. Miss tại cùng efSearch giảm từ **{pp(c4['pic2word']['overall_miss']['before']):.2f}%** xuống **{pp(c4['pic2word']['overall_miss']['after']):.2f}%**, nhưng so sánh này chưa khớp `ndis` hoặc mật độ.",'', 'C4 mô tả thay đổi phân phối và đồ thị, không chứng minh MCS hay bậc vào gây ra thay đổi retention. Phân rã giữa model dùng seed 42 là phân tích mô tả bổ sung, không phải phân rã nhân quả hiệu ứng centering. [Báo cáo C4 chi tiết](./C4/bao_cao_C4_chi_tiet.md).','', '## C5 — Query nào có gain lớn hơn?','', f"Chia query thành năm nhóm `s1` riêng trong mỗi backbone, tại cùng `efSearch=128`. Với Pic2Word, gain trung bình nhóm `s1` thấp nhất là **{pp(k['groups'][0]['gain']):+.2f} điểm %**, nhóm cao nhất là **{pp(k['groups'][-1]['gain']):+.2f} điểm %**; chênh lệch thấp nhất − cao nhất **{pp(k['contrast_low_minus_high']['estimate']):+.2f} điểm %**, CI query 95% [{pp(k['contrast_low_minus_high']['ci_query'][0]):+.2f}; {pp(k['contrast_low_minus_high']['ci_query'][1]):+.2f}]. Dự đoán được **ủng hộ một phần**: hai đầu khác nhau theo hướng dự đoán nhưng năm giá trị trung bình không giảm đơn điệu hoàn toàn.",'', f"Với SEARLE, chênh lệch hai nhóm đầu cuối là **{pp(v['contrast_low_minus_high']['estimate']):+.2f} điểm %**, CI 95% [{pp(v['contrast_low_minus_high']['ci_query'][0]):+.2f}; {pp(v['contrast_low_minus_high']['ci_query'][1]):+.2f}]; chưa đủ bằng chứng theo quy tắc đã đăng ký. C5 không khớp `ndis` theo từng nhóm. [Báo cáo C5](./C5/bao_cao_C5.md).",'', '## Giới hạn chung và việc tiếp theo','', '- ID nguồn của 800 test feature rows chưa được xác minh độc lập từng hàng; việc ghép query dùng thứ tự extraction/annotation và được kiểm tra nhất quán nội bộ.', '- Chỉ có năm seed; bootstrap theo query chưa giải quyết đầy đủ phụ thuộc do nhiều query cùng gặp một ảnh. Các CI theo từng điểm/nhóm không điều chỉnh đồng thời cho nhiều so sánh.', '- Các kết quả chỉ áp dụng trực tiếp cho CIRCO, các backbone và cấu hình đã đo; workspace dirty nên provenance dựa vào hash tệp và manifest.', '- Ưu tiên thiết kế đối chứng C2 bổ sung có số cạnh khớp theo ngưỡng đăng ký và miền `ndis` chung. Sau đó có thể đánh giá H-MG và tiếp tục theo kế hoạch R3; không xem C4/C5 là bằng chứng nhân quả.','', 'Nguồn dữ liệu số: [C1](./C1/results.json), [C2](./C2/results.json), [C3](./C3/revision_v2/results.json), [C4](./C4/results.json), [C5](./C5/results.json).']
    (P/'tong_hop_C1_C5.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
if __name__=='__main__':main()
